<script setup>
/*
 * RKS 历史：选一个版本，按那一版的定数取最高的 30 张谱面，
 * 用当期公式全部打满试算 RKS；榜单版式与「B30 列表」一致。
 */
import { computed, onMounted, ref } from 'vue'
import { useOpenSong } from '../../api/openSong.js'
import { compareVersion, loadLevelHistory, valueAt } from '../../api/levelHistory.js'
import { RKS_ERAS, eraOf } from '../../api/rksHistory.js'
import { chartCover, difColor, formatRks } from '../../api/common.js'
import { useRemScale } from '../../utils/rem.js'
import ScrollTabs from '../../components/ui/ScrollTabs.vue'
import b30Card from '../../components/cards/b30Card.vue'

useRemScale()

const openSong = useOpenSong()

const history = ref(null)
const versions = ref([])
const selectedVersion = ref('')

onMounted(async () => {
  history.value = await loadLevelHistory()
  versions.value = history.value?.versions || []
  selectedVersion.value = versions.value[versions.value.length - 1] || ''
})

// 这一版能打、且定数最高的 30 张（只算 IN / AT，与「B30 列表」一致）
const charts = computed(() => {
  const data = history.value
  const version = selectedVersion.value
  if (!data || !version) return []
  const list = []
  for (const [key, song] of Object.entries(data.songs)) {
    if (song.hidden) continue
    if (compareVersion(song.added, version) > 0) continue
    if (song.removed && compareVersion(version, song.removed) > 0) continue
    const illVariant = valueAt(song.ill || [], version)
    for (const diff of ['IN', 'AT']) {
      if (diff === 'AT' && song.at && compareVersion(version, song.at) < 0) continue
      const timeline = song.diffs?.[diff]
      if (!timeline) continue
      const level = valueAt(timeline, version)
      if (!level) continue
      list.push({ key, name: song.name, diff, level, cover: chartCover(key, diff, illVariant) })
    }
  }
  // 与 getB30 一样只按定数降序排（同分保持 infos 里的顺序），两页榜单才对得上
  list.sort((a, b) => b.level - a.level)
  return list.slice(0, 30)
})

// 选中的版本落在哪一版公式里
const eraIndex = computed(() => (selectedVersion.value ? RKS_ERAS.indexOf(eraOf(selectedVersion.value)) : 0))

// 这一版全部打满时的 RKS
const rks = computed(() => {
  const value = charts.value.length ? RKS_ERAS[eraIndex.value].calc(charts.value.map((chart) => chart.level)) : 0
  return { text: value.toFixed(2), detail: formatRks(value) }
})

// 卡片数据，字段顺序与 api/levels.js 的 getB30 一致：
// [键名, 定数, 曲绘, 曲名, 难度名, 难度色, 右上角文字, 是否高亮]
// 版式照搬 B30：算两次的谱面先以 [P] 出现一次，再在 [B] 里出现一次；
// 只列这一版公式真正计入的谱面（①版 19 张、②版含重复共 20 张、③版共 30 张）。
const b30List = computed(() => {
  const limit = eraIndex.value === 2 ? 27 : 19
  const pCount = eraIndex.value === 2 ? 3 : eraIndex.value === 1 ? 1 : 0
  const counted = charts.value.slice(0, limit)
  const toCard = (chart, label, glow) => [
    chart.key,
    Math.round(chart.level * 10) / 10,
    chart.cover,
    chart.name,
    chart.diff,
    difColor(chart.diff),
    label,
    glow
  ]
  const cards = counted.slice(0, pCount).map((chart, index) => toCard(chart, `[P${index + 1}]`, true))
  counted.forEach((chart, index) => cards.push(toCard(chart, `[B${index + 1}]`, false)))
  return cards
})
</script>

<template>
  <div class="dt-page">
    <div class="version-row">
      <ScrollTabs v-model="selectedVersion" :items="versions" class="version-tabs" aria-label="选择版本" />
    </div>
    <div class="rks-row">
      <div class="rks">
        <span class="rks__label">RKS</span>
        <span class="rks__value">{{ rks.text }}</span>
        <span class="rks__detail">（{{ rks.detail }}）</span>
      </div>
    </div>

    <div class="b30-list">
      <div class="card-grid">
        <b30Card
          v-for="(item, index) in b30List"
          :key="item[0] + item[4] + index"
          :chart-info="item"
          @click="openSong(item[0])"
        />
      </div>
    </div>
    <p v-if="!b30List.length" class="dt-empty">这一版还没有谱面定数数据。</p>
  </div>
</template>

