/**
 * 定数历史页的取数：/files/lvmdf/history.json 里是每首曲目的定数时间线，
 * 选好版本后由页面现场还原那一刻的列表（数据由 python/getLevelHistory.py 生成）。
 */
import { loadJson } from './jsonCache.js'

export const HISTORY_PATH = '/files/lvmdf/history.json'

export function loadLevelHistory() {
  return loadJson(HISTORY_PATH)
}

/** 版本号拆成数字：3.17.0.1 → [3, 17, 0, 1] */
export function versionKey(version) {
  return String(version)
    .split('.')
    .map((segment) => Number(segment) || 0)
}

/** 版本号比较：a 早于 b 返回负数，相等 0，晚于返回正数（3.9.0 < 3.10.2） */
export function compareVersion(a, b) {
  const left = versionKey(a)
  const right = versionKey(b)
  const length = Math.max(left.length, right.length)
  for (let i = 0; i < length; i += 1) {
    const diff = (left[i] || 0) - (right[i] || 0)
    if (diff) return diff
  }
  return 0
}

/**
 * 取时间线上「该版本起生效」的取值。
 * timeline 形如 [[版本, 值], …]，按版本升序；版本早于第一条时返回 0。
 */
export function valueAt(timeline, version) {
  let value = 0
  for (const [ver, val] of timeline) {
    if (compareVersion(ver, version) > 0) break
    value = val
  }
  return value
}
