/**
 * RKS 历史：各版本时期的 RKS 计算公式，以及按版本取定数做的试算。
 * 每张谱面算几次见 weightOf；试算用的候选谱面由页面按所选版本的定数现算。
 */
import { compareVersion } from './levelHistory.js'

/**
 * 三版公式。calc 接收按定数降序排好的谱面定数（相当于这些谱面全部打满）。
 * 第①版只取前 19 张、除 20：最高那张不额外加，所以「P 只算一次」。
 */
export const RKS_ERAS = [
  {
    label: '第①版',
    range: '1.0.0 ~ 1.4.7',
    formula: 'sum(最高 19 张) / 20',
    hint: '最高分只算一次',
    sample: '回算 13 份历史存档：5 份逐位一致，其余偏差不超过 0.035',
    calc: (levels) => levels.slice(0, 19).reduce((sum, lvl) => sum + lvl, 0) / 20
  },
  {
    label: '第②版',
    range: '1.5.0 ~ 3.10.4',
    formula: '(P1 + sum(最高 19 张)) / 20',
    hint: '最高那张再加一次',
    sample: '回算 25 份历史存档：22 份逐位一致，其余偏差来自回填的定数',
    calc: (levels) => (levels[0] + levels.slice(0, 19).reduce((sum, lvl) => sum + lvl, 0)) / 20
  },
  {
    label: '第③版',
    range: '3.11.0 ~ 现在',
    formula: '(sum(最高 3 张) + sum(最高 27 张)) / 30',
    hint: '最高 3 张各加两次',
    sample: '回算 8 份历史存档：全部逐位一致',
    calc: (levels) =>
      (levels.slice(0, 3).reduce((sum, lvl) => sum + lvl, 0) +
        levels.slice(0, 27).reduce((sum, lvl) => sum + lvl, 0)) /
      30
  }
]

/** 这个版本用的是哪一版公式 */
export function eraOf(version) {
  if (compareVersion(version, '3.11.0') >= 0) return RKS_ERAS[2]
  if (compareVersion(version, '1.5.0') >= 0) return RKS_ERAS[1]
  return RKS_ERAS[0]
}

/** 这一版公式里第 index 张（从 1 起）算几次：0 表示不进 RKS */
export function weightOf(eraIndex, rank) {
  if (eraIndex === 0) return rank <= 19 ? 1 : 0
  if (eraIndex === 1) return rank === 1 ? 2 : rank <= 19 ? 1 : 0
  return rank <= 3 ? 2 : rank <= 27 ? 1 : 0
}
